#!/usr/bin/env Rscript
# Apply reviewed formal annotation to the deterministic Phase 1 object.
suppressPackageStartupMessages({ library(Seurat); library(SeuratObject); library(ggplot2); library(digest) })
project_root <- "D:/Users/lstsw/Documents/Adipose_derived stromal_metabolic niches/adipose_stromal_metabolic_niche_lit/public_data_analysis/GSE161529_ASC_P_validation"
input_rds <- file.path(project_root, "outputs", "ERTotal_cluster1_TNK_Harmony_optimized", "ERTotal_cluster1_Harmony_optimized.rds")
annotation_file <- file.path(project_root, "tables", "ERTotal_cluster1_optimized_formal_annotation.tsv")
output_dir <- file.path(project_root, "outputs", "ERTotal_cluster1_TNK_Harmony_optimized_formal_annotation")
overwrite <- identical(Sys.getenv("ERTOTAL_TNK_FORMAL_ANNOTATION_OVERWRITE"), "1")
if (!file.exists(input_rds) || !file.exists(annotation_file)) stop("Missing optimized RDS or formal annotation table.")
dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
if (length(list.files(output_dir, all.files = TRUE, no.. = TRUE)) && !overwrite) stop("Output directory is non-empty; set ERTOTAL_TNK_FORMAL_ANNOTATION_OVERWRITE=1 to rerun.")
write_tsv <- function(x, name) write.table(x, file.path(output_dir, name), sep = "\t", quote = FALSE, row.names = FALSE, na = "")
obj <- readRDS(input_rds)
if (!"optimized_cluster" %in% colnames(obj[[]])) stop("optimized_cluster metadata is absent.")
ann <- read.delim(annotation_file, check.names = FALSE, stringsAsFactors = FALSE)
required <- c("cluster", "n_cells", "celltype_final", "short_label", "compartment", "CD4_analysis_role", "confidence", "key_positive_markers", "interpretation_note")
if (!all(required %in% colnames(ann)) || anyDuplicated(ann$cluster)) stop("Formal annotation table is malformed.")
ann$cluster <- as.character(ann$cluster)
clusters <- as.character(obj$optimized_cluster)
if (!setequal(unique(clusters), ann$cluster)) stop("Formal annotation table does not exactly cover optimized clusters.")
observed_n <- as.integer(table(factor(clusters, levels = ann$cluster)))
if (!identical(observed_n, as.integer(ann$n_cells))) stop("Annotation n_cells does not match the RDS.")
idx <- match(clusters, ann$cluster)
obj$formal_celltype <- factor(ann$celltype_final[idx], levels = ann$celltype_final)
obj$formal_short_label <- factor(ann$short_label[idx], levels = ann$short_label)
obj$CD4_analysis_role <- factor(ann$CD4_analysis_role[idx], levels = unique(ann$CD4_analysis_role))
obj$formal_annotation_version <- "2026-07-17_reviewed_7cluster_v1"
cell_table <- data.frame(cell_id = colnames(obj), optimized_cluster = clusters, formal_celltype = as.character(obj$formal_celltype), formal_short_label = as.character(obj$formal_short_label), CD4_analysis_role = as.character(obj$CD4_analysis_role), patient_id = as.character(obj$patient_id), stringsAsFactors = FALSE)
write_tsv(ann, "ERTotal_cluster1_optimized_formal_annotation.tsv")
write_tsv(cell_table, "ERTotal_cluster1_optimized_formal_cell_annotation.tsv")
summary_table <- merge(ann[, c("cluster", "short_label", "CD4_analysis_role", "confidence")], as.data.frame(table(cluster = clusters), stringsAsFactors = FALSE), by.x = "cluster", by.y = "cluster", sort = FALSE)
names(summary_table)[5] <- "observed_n_cells"
write_tsv(summary_table, "ERTotal_cluster1_optimized_formal_annotation_summary.tsv")
p <- DimPlot(obj, reduction = "umap_optimized", group.by = "formal_short_label", label = TRUE, repel = TRUE, label.size = 3, pt.size = 0.25) + coord_fixed() + labs(title = "ERTotal cluster 1: formal 7-cluster annotation", colour = NULL) + theme_classic(base_size = 11) + theme(legend.position = "bottom", legend.text = element_text(size = 8)) + guides(colour = guide_legend(nrow = 2, byrow = TRUE))
ggsave(file.path(output_dir, "Reviewer_Figure_ERTotal_cluster1_formal_annotation.png"), p, width = 11, height = 8, dpi = 320, bg = "white")
ggsave(file.path(output_dir, "Reviewer_Figure_ERTotal_cluster1_formal_annotation.pdf"), p, width = 11, height = 8, bg = "white")
saveRDS(obj, file.path(output_dir, "ERTotal_cluster1_Harmony_optimized_formal_annotation.rds"), compress = "xz")
writeLines(capture.output(sessionInfo()), file.path(output_dir, "ERTotal_cluster1_optimized_formal_annotation_sessionInfo.txt"))
writeLines(c("# Formal cluster annotation", paste0("Input RDS SHA256: ", digest(file = input_rds, algo = "sha256")), paste0("Annotation TSV SHA256: ", digest(file = annotation_file, algo = "sha256")), "Annotation is based on reviewed 7-cluster FindAllMarkers output and is descriptive, not inferential differential expression.", "Cluster 1 is the only primary CD4 Tconv input; cluster 2 is the only primary Treg input."), file.path(output_dir, "ERTotal_cluster1_optimized_formal_annotation_RUN_REPORT.md"))
